t;min-height:40px!important;border-radius:10px!important;padding:9px 12px!important;font-family:var(--body)!important;font-size:13.5px!important;background:var(--panel)!important;border:1px solid var(--border)!important;box-shadow:none!important}.lp-tab-panel .form-field textarea{min-height:68px!important;resize:none;line-height:1.5}.lp-tab-panel .form-field input:focus,.lp-tab-panel .form-field select:focus,.lp-tab-panel .form-field textarea:focus{outline:none!important;border-color:var(--gold)!important;box-shadow:0 0 0 3px var(--gold-dim)!important}.lp-card{border-radius:12px!important;padding:12px 14px!important;margin-bottom:10px!important;background:var(--panel-alt)!important}.lp-card-title{font-family:var(--body)!important;font-size:11px!important;letter-spacing:.08em!important;margin-bottom:8px!important}.lp-form-actions{margin-top:16px!important;padding-top:14px!important;border-top:1px solid var(--border-soft)!important;display:flex!important;justify-content:flex-start!important}.lp-form-actions .btn{min-height:42px!important;padding:9px 20px!important;border-radius:10px!important;font-size:12px!important;font-weight:700!important;letter-spacing:.03em!important}.lp-preview-panel>.panel-head{padding:20px 24px 14px!important}.lp-preview-body{padding:0 24px 24px!important}.lp-browser-frame{border-radius:12px!important}@media(max-width:760px){.lp-panel>.panel-head{padding:16px 16px 12px!important}.lp-panel form{padding:0 16px 88px!important}.lp-tab{flex:1 1 calc(50% - 8px);justify-content:center}}
