<script>
(function(){function initSidebarBackdrop(sidebar){if(!sidebar||sidebar.dataset.backdropBound==='1')return;sidebar.dataset.backdropBound='1';var backdrop=document.createElement('div');backdrop.className='sidebar-backdrop';backdrop.setAttribute('aria-hidden','true');if(sidebar.parentNode)sidebar.parentNode.insertBefore(backdrop,sidebar.nextSibling);else document.body.appendChild(backdrop);backdrop.addEventListener('click',function(){sidebar.classList.remove('open')});function sync(){backdrop.classList.toggle('open',sidebar.classList.contains('open'))}new MutationObserver(sync).observe(sidebar,{attributes:true,attributeFilter:['class']});sync()}function enforceMobileSidebarExpanded(sidebar){if(!sidebar||sidebar.dataset.mobileExpandBound==='1')return;sidebar.dataset.mobileExpandBound='1';function apply(){if(window.innerWidth<=900)sidebar.classList.remove('collapsed')}apply();window.addEventListener('resize',apply)}function initRoleUi(){var sidebar=document.getElementById('sidebar'),menuBtn=document.getElementById('menuBtn');if(sidebar){initSidebarBackdrop(sidebar);enforceMobileSidebarExpanded(sidebar);}if(menuBtn&&sidebar&&!menuBtn.dataset.uiBound){menuBtn.dataset.uiBound='1';menuBtn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();sidebar.classList.toggle('open')})}var themeBtn=document.getElementById('themeToggleBtn');if(themeBtn&&!themeBtn.dataset.uiBound){themeBtn.dataset.uiBound='1';var key='siberad-theme';function applyTheme(theme){if(theme==='light')document.documentElement.setAttribute('data-theme','light');else document.documentElement.removeAttribute('data-theme');themeBtn.setAttribute('aria-pressed',theme==='light'?'true':'false')}var saved='dark';try{saved=localStorage.getItem(key)||'dark'}catch(err){}applyTheme(saved);themeBtn.addEventListener('click',function(){var current=document.documentElement.getAttribute('data-theme')==='light'?'light':'dark',next=current==='light'?'dark':'light';try{localStorage.setItem(key,next)}catch(err){}applyTheme(next)})}var profileBtn=document.getElementById('profileMenuBtn'),profileDrop=document.getElementById('profileDropdown');if(profileBtn&&profileDrop&&!profileBtn.dataset.uiBound){profileBtn.dataset.uiBound='1';profileBtn.addEventListener('click',function(e){e.stopPropagation();profileDrop.classList.toggle('open')});document.addEventListener('click',function(e){if(!profileDrop.parentElement.contains(e.target))profileDrop.classList.remove('open')})}window.openProfileModal=window.openProfileModal||function(id){var overlay=document.getElementById('profileModalOverlay');if(!overlay)return;overlay.querySelectorAll('.profile-dropdown-view').forEach(function(view){view.style.display=view.id===id?'block':'none'});overlay.classList.add('open');if(profileDrop)profileDrop.classList.remove('open')};var closeProfile=document.getElementById('profileModalCloseBtn');if(closeProfile&&!closeProfile.dataset.uiBound){closeProfile.dataset.uiBound='1';closeProfile.addEventListener('click',function(){var overlay=document.getElementById('profileModalOverlay');if(overlay)overlay.classList.remove('open')})}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initRoleUi);else initRoleUi()})();
</script>
<script>
(function(){function normalisasiNamaLogAktivitas(){var table=document.getElementById('tblLogAktivitas');if(!table)return;var normalisasi={'BINMAT':'Binmat','BINFUNG':'Binfung','BINUM':'Binum','DIKLAT':'Diklat'};table.querySelectorAll('tbody tr').forEach(function(row){var cells=row.children;if(cells.length<2)return;var pengguna=cells[1],teks=pengguna.textContent;Object.keys(normalisasi).forEach(function(nama){teks=teks.replace(new RegExp('\\b'+nama+'\\b','g'),normalisasi[nama])});pengguna.textContent=teks})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',normalisasiNamaLogAktivitas);else normalisasiNamaLogAktivitas()})();
</script>
<script>
(function(){function removeOnlyPreviewToolbar(frame){if(!frame)return;frame.style.overflowX='hidden';frame.style.overflowY='auto';var zoomToolbar=frame.querySelector('.lp-zoom-toolbar');if(zoomToolbar)zoomToolbar.remove();Array.prototype.slice.call(frame.children).forEach(function(child){if(child.classList.contains('lp-browser-bar')||child.classList.contains('lp-preview'))return;var text=(child.textContent||'').replace(/\s+/g,' ').trim().toLowerCase(),buttons=child.querySelectorAll?child.querySelectorAll('button'):[],hasOnlyFitButton=buttons.length===1&&(buttons[0].textContent||'').trim().toLowerCase()==='fit';if(text==='fit'||hasOnlyFitButton)child.remove()})}function setupLandingPreview(){document.querySelectorAll('.lp-browser-frame').forEach(function(frame){removeOnlyPreviewToolbar(frame);if(frame.dataset.previewToolbarGuard==='1')return;frame.dataset.previewToolbarGuard='1';var observer=new MutationObserver(function(){removeOnlyPreviewToolbar(frame)});observer.observe(frame,{childList:true,subtree:true})})}function blockRealLoginInPreview(frame){if(!frame)return;var iframe=frame.querySelector('#lpLiveLandingFrame');if(!iframe||iframe.dataset.previewLoginGuard==='1')return;iframe.dataset.previewLoginGuard='1';iframe.addEventListener('load',function(){try{var doc=iframe.contentDocument||iframe.contentWindow.document;if(!doc)return;doc.querySelectorAll('form').forEach(function(form){if(form.dataset.previewLoginBlocked==='1')return;form.dataset.previewLoginBlocked='1';form.addEventListener('submit',function(event){event.preventDefault();event.stopImmediatePropagation()},true)})}catch(error){}})}function init(){setupLandingPreview();document.querySelectorAll('.lp-browser-frame').forEach(blockRealLoginInPreview)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();var rootObserver=new MutationObserver(init);rootObserver.observe(document.body,{childList:true,subtree:true});window.setTimeout(function(){rootObserver.disconnect()},5000)})();
</script>

